def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            top = min(y for y, x in cells)
            left = min(x for y, x in cells)
            bottom = max(y for y, x in cells)
            right = max(x for y, x in cells)
            obj = [[0] * (right - left + 1) for _ in range(bottom - top + 1)]
            for y, x in cells:
                obj[y - top][x - left] = color
            objects.append((top, left, color, obj))

    hollow, solid = [], []
    for top, left, color, obj in objects:
        if any(0 in row for row in obj):
            hollow.append((top, left, obj))
        else:
            solid.append((top, left, obj))

    hollow.sort(key=lambda item: (item[0], item[1]))
    solid.sort(key=lambda item: (item[0], item[1]))

    rows = []
    for i in range(max(len(hollow), len(solid))):
        row_block = [[0] * 8 for _ in range(4)]
        for offset, group in ((0, hollow), (4, solid)):
            if i < len(group):
                obj = group[i][2]
                for y in range(min(4, len(obj))):
                    for x in range(min(4, len(obj[0]))):
                        row_block[y][offset + x] = obj[y][x]
        rows.extend(row_block)
    return rows
